// Comprueba la firma de xenxo (X-Xenxo-Signature: t=<ms>,v1=<hex>, HMAC-SHA256 de "<t>.<cuerpo>").
// Necesita en n8n: NODE_FUNCTION_ALLOW_BUILTIN=crypto, N8N_BLOCK_ENV_ACCESS_IN_NODE=false y
// XENXO_N8N_SECRET (el mismo valor que N8N_WEBHOOK_SECRET en xenxo). Sin firma válida, se descarta.
const crypto = require('crypto');
const secret = $env.XENXO_N8N_SECRET;
const out = [];
for (const item of $input.all()) {
  const h = item.json.headers || {};
  const m = /^t=(\d+),v1=([0-9a-f]{64})$/.exec(h['x-xenxo-signature'] || '');
  if (!m || !secret) continue;
  const body = JSON.stringify(item.json.body);
  const want = crypto.createHmac('sha256', secret).update(`${m[1]}.${body}`).digest('hex');
  const fresh = Math.abs(Date.now() - Number(m[1])) < 5 * 60 * 1000;
  if (fresh && crypto.timingSafeEqual(Buffer.from(want), Buffer.from(m[2]))) out.push({ json: item.json.body });
}
return out;

// Un mensaje corto por aviso. Lo que llega es dato: no lleva quién denuncia ni textos de nadie.
const panel = 'https://xenxo.io (Panel → Moderación)';
const reasons = { illegal: 'ilegal', hate: 'odio', harassment: 'acoso', sexual: 'sexual', minors: 'menores', violence: 'violencia', spam: 'spam', ip: 'propiedad intelectual', other: 'otro' };
return $input.all().map(({ json: e }) => {
  let text;
  switch (e.event) {
    case 'project.pending': text = `Proyecto por revisar: «${e.title}»${e.district ? ` (distrito ${e.district})` : ''}`; break;
    case 'game.pending': text = `Juego por revisar (ficha nueva o cambiada): «${e.title}»`; break;
    case 'report.open': text = `Denuncia nueva #${e.id}: ${e.target_type}, motivo ${reasons[e.reason] || e.reason}`; break;
    case 'district.pending': text = `Distrito de la comunidad por revisar: ${e.slug}`; break;
    case 'node.down': text = `El nodo ${e.id} no responde: ${e.chunks} distrito(s) han vuelto a Cloudflare con su última copia`; break;
    default: text = `Aviso de xenxo: ${e.event}`;
  }
  return { json: { text: `${text}\n${panel}`, event: e.event } };
});
